{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "com.tapetide/stock-research-mcp",
  "description": "NSE & BSE Indian stock market data MCP — quotes, screener, financials, FII/DII flows & portfolio",
  "repository": {
    "url": "https://github.com/Tapetide-hq/nse-bse-indian-stock-market-data-mcp",
    "source": "github"
  },
  "version": "1.0.6",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "tapetide-mcp",
      "version": "1.0.6",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "API token from https://tapetide.com/settings/tokens (free, starts with tpt_rt_)",
          "isRequired": true,
          "format": "string",
          "isSecret": true,
          "name": "TAPETIDE_TOKEN"
        }
      ]
    }
  ],
  "remoteEndpoints": [
    {
      "url": "https://mcp.tapetide.com/mcp",
      "transport": {
        "type": "http"
      },
      "authentication": {
        "type": "oauth2",
        "authorizationUrl": "https://mcp.tapetide.com/authorize",
        "tokenUrl": "https://mcp.tapetide.com/token",
        "registrationUrl": "https://mcp.tapetide.com/register",
        "scopes": ["openid", "email"]
      }
    }
  ]
}
